/// <summary>
/// PricingAttribute of table <c>InventTable</c> field OrigCountyId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableOrigCountyId extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, OrigCountyId);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::String);
    InventTable inventTable;

    while select inventTable
        group by OrigCountyId
    {
        if (! ret.in(inventTable.OrigCountyId))
        {
            ret.add(inventTable.OrigCountyId);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, OrigCountyId));
    qbr.value(queryValue(_value));
}
